#!/usr/bin/env python3
from pathlib import Path
import subprocess, sys, re

FILES = {
    "seed_organism_notes_v89.py": "\nimport json, subprocess, time\nfrom datetime import datetime\nfrom pathlib import Path\n\nNOTES_FILE = Path(\"seed_organism_notes_v89.jsonl\")\nQUESTIONS_FILE = Path(\"seed_organism_questions_v89.jsonl\")\nSETTINGS_FILE = Path(\"seed_organism_notes_v89_settings.json\")\n\nDEFAULTS = {\n    \"version\": \"v89.1.0\",\n    \"max_notes\": 2000,\n    \"ask_enabled\": True,\n    \"min_importance_to_ask\": 82,\n    \"min_seconds_between_questions\": 900,\n    \"speak_questions\": True,\n    \"store_raw_audio\": False,\n    \"store_raw_screenshots\": False,\n    \"store_raw_transcripts\": False,\n    \"note_only_mode\": True,\n    \"reject_prompt_leak\": True\n}\n\nBAD_SUMMARY_FRAGMENTS = [\n    \"return only json\",\n    \"inspect this temporary screenshot\",\n    \"importance 0-100\",\n    \"summary, question, tags\",\n    \"altan wants no screenshots saved\",\n    \"seed ambient vision filter\",\n    \"seed ambient hearing filter\",\n    \"store no private raw image data\"\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef settings():\n    if SETTINGS_FILE.exists():\n        try:\n            d = DEFAULTS.copy()\n            d.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            d[\"version\"] = \"v89.1.0\"\n            return d\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef write(path, row):\n    row.setdefault(\"created_at\", now())\n    row.setdefault(\"version\", \"v89.1.0\")\n    with path.open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n\ndef read(path, limit=200):\n    if not path.exists():\n        return []\n    out = []\n    for line in path.read_text(errors=\"ignore\").splitlines()[-limit:]:\n        try:\n            out.append(json.loads(line))\n        except Exception:\n            pass\n    return out\n\ndef is_bad_summary(summary):\n    s = \" \".join(str(summary or \"\").lower().split())\n    return any(x in s for x in BAD_SUMMARY_FRAGMENTS)\n\ndef clean_summary(summary):\n    summary = str(summary or \"\").strip()\n    if is_bad_summary(summary):\n        return \"\"\n    return summary[:1200]\n\ndef trim():\n    max_notes = int(settings().get(\"max_notes\", 2000))\n    if NOTES_FILE.exists():\n        lines = NOTES_FILE.read_text(errors=\"ignore\").splitlines()\n        if len(lines) > max_notes:\n            NOTES_FILE.write_text(\"\\n\".join(lines[-max_notes:]) + \"\\n\")\n\ndef say(txt):\n    if not settings().get(\"speak_questions\", True):\n        return False\n    try:\n        from seed_voice_v76 import say_with_settings\n        return say_with_settings(txt)\n    except Exception:\n        try:\n            import shutil\n            b = shutil.which(\"say\")\n            if b:\n                subprocess.run([b, str(txt)[:800]], timeout=60)\n                return True\n        except Exception:\n            pass\n    return False\n\ndef last_question_age():\n    q = read(QUESTIONS_FILE, 1000)\n    if not q:\n        return 999999\n    try:\n        return (datetime.now() - datetime.fromisoformat(q[-1][\"created_at\"])).total_seconds()\n    except Exception:\n        return 999999\n\ndef maybe_ask(note):\n    s = settings()\n    if not s.get(\"ask_enabled\", True):\n        return {\"asked\": False, \"reason\": \"disabled\"}\n    if int(note.get(\"importance\", 0)) < int(s.get(\"min_importance_to_ask\", 82)):\n        return {\"asked\": False, \"reason\": \"importance\"}\n    if last_question_age() < float(s.get(\"min_seconds_between_questions\", 900)):\n        return {\"asked\": False, \"reason\": \"cooldown\"}\n    q = (note.get(\"question\") or \"\").strip()\n    if not q or is_bad_summary(q):\n        return {\"asked\": False, \"reason\": \"no good question\"}\n    try:\n        from seed_avatar_v89 import set_avatar_state\n        set_avatar_state(mode=\"curious\", emotion=\"curious\", message=q)\n    except Exception:\n        pass\n    spoke = say(q)\n    write(QUESTIONS_FILE, {\"note_id\": note.get(\"id\"), \"question\": q, \"spoke\": spoke})\n    return {\"asked\": True, \"spoke\": spoke, \"question\": q}\n\ndef add_note(source, summary, importance=50, question=\"\", tags=None, metadata=None):\n    cleaned = clean_summary(summary)\n    if not cleaned:\n        return {\"ok\": False, \"blocked\": True, \"reason\": \"prompt leak or empty summary rejected\", \"source\": source}\n\n    q = \"\" if is_bad_summary(question) else str(question or \"\").strip()[:500]\n    note = {\n        \"id\": f\"note_{int(time.time()*1000)}\",\n        \"source\": source,\n        \"summary\": cleaned,\n        \"importance\": int(importance),\n        \"question\": q,\n        \"tags\": tags or [],\n        \"metadata\": metadata or {},\n        \"raw_audio_saved\": False,\n        \"raw_screenshot_saved\": False,\n        \"raw_transcript_saved\": False,\n        \"note_only_mode\": True\n    }\n    write(NOTES_FILE, note)\n    trim()\n    try:\n        from seed_avatar_v89 import set_avatar_state\n        set_avatar_state(mode=\"noting\", emotion=\"attentive\", message=note[\"summary\"], last_note=note)\n    except Exception:\n        pass\n    return {\"ok\": True, \"note\": note, \"ask\": maybe_ask(note)}\n\ndef clean_bad_notes():\n    if not NOTES_FILE.exists():\n        return {\"ok\": True, \"removed\": 0, \"kept\": 0}\n    kept, removed = [], 0\n    for line in NOTES_FILE.read_text(errors=\"ignore\").splitlines():\n        try:\n            row = json.loads(line)\n        except Exception:\n            continue\n        if is_bad_summary(row.get(\"summary\", \"\")):\n            removed += 1\n        else:\n            kept.append(row)\n    NOTES_FILE.write_text(\"\\n\".join(json.dumps(r, ensure_ascii=False) for r in kept) + (\"\\n\" if kept else \"\"))\n    return {\"ok\": True, \"removed\": removed, \"kept\": len(kept)}\n\ndef latest_notes(limit=10):\n    return read(NOTES_FILE, limit)\n\ndef note_stats():\n    rows = read(NOTES_FILE, 5000)\n    by = {}\n    for r in rows:\n        by[r.get(\"source\", \"unknown\")] = by.get(r.get(\"source\", \"unknown\"), 0) + 1\n    return {\"created_at\": now(), \"version\": \"v89.1.0\", \"ok\": True, \"count\": len(rows), \"by_source\": by, \"latest\": rows[-5:], \"settings\": settings()}\n\ndef show_notes(n=10):\n    print(json.dumps(latest_notes(n), indent=4, ensure_ascii=False))\n\ndef show_stats():\n    print(json.dumps(note_stats(), indent=4, ensure_ascii=False))\n\nif __name__ == \"__main__\":\n    import sys\n    a = sys.argv[1] if len(sys.argv) > 1 else \"stats\"\n    if a == \"latest\":\n        show_notes(int(sys.argv[2]) if len(sys.argv) > 2 else 10)\n    elif a == \"add\":\n        print(add_note(\"manual\", \" \".join(sys.argv[2:]) or \"manual note\", 60))\n    elif a == \"clean\":\n        print(clean_bad_notes())\n    else:\n        show_stats()\n",
    "seed_ambient_vision_v89.py": "\nimport base64, json, os, signal, subprocess, sys, time, urllib.request\nfrom datetime import datetime\nfrom pathlib import Path\n\nSETTINGS_FILE = Path(\"seed_ambient_vision_v89_settings.json\")\nPID_FILE = Path(\"seed_ambient_vision_v89.pid\")\nSTOP_FILE = Path(\"seed_ambient_vision_v89.stop\")\nLOG_FILE = Path(\"seed_ambient_vision_v89.log\")\nSTATUS_FILE = Path(\"seed_ambient_vision_v89_status.json\")\nTEMP_DIR = Path(\"seed_ambient_vision_v89_temp\")\n\nDEFAULTS = {\n    \"version\": \"v89.1.0\",\n    \"enabled\": True,\n    \"interval_seconds\": 90,\n    \"min_importance_to_note\": 64,\n    \"vision_model\": \"gemma3:4b\",\n    \"ollama_url\": \"http://localhost:11434/api/generate\",\n    \"delete_screenshot_after_note\": True,\n    \"store_raw_screenshots\": False,\n    \"fallback_to_window_note\": True\n}\n\nBAD_FRAGMENTS = [\n    \"return only json\",\n    \"inspect this temporary screenshot\",\n    \"importance 0-100\",\n    \"summary, question, tags\",\n    \"altan wants no screenshots saved\",\n    \"seed ambient vision filter\"\n]\n\n_last = None\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef settings():\n    if SETTINGS_FILE.exists():\n        try:\n            d = DEFAULTS.copy()\n            d.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            d[\"version\"] = \"v89.1.0\"\n            return d\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef status(**kw):\n    d = {\"created_at\": now(), \"version\": \"v89.1.0\"}\n    d.update(kw)\n    STATUS_FILE.write_text(json.dumps(d, indent=4, ensure_ascii=False))\n    return d\n\ndef avatar(mode, msg):\n    try:\n        from seed_avatar_v89 import set_avatar_state\n        set_avatar_state(mode=mode, emotion=mode, message=msg, seeing=(mode==\"seeing\"), thinking=(mode==\"thinking\"))\n    except Exception:\n        pass\n\ndef window():\n    script = 'tell application \"System Events\" to set frontApp to name of first application process whose frontmost is true\\ntry\\n tell application \"System Events\" to tell process frontApp to set winTitle to name of front window\\non error\\n set winTitle to \"\"\\nend try\\nreturn frontApp & \" | \" & winTitle'\n    try:\n        p = subprocess.run([\"osascript\", \"-e\", script], capture_output=True, text=True, timeout=10)\n        out = p.stdout.strip()\n        if \" | \" in out:\n            app, title = out.split(\" | \", 1)\n        else:\n            app, title = out, \"\"\n        return {\"ok\": p.returncode == 0, \"app\": app, \"title\": title}\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e)}\n\ndef shot():\n    TEMP_DIR.mkdir(exist_ok=True)\n    f = TEMP_DIR / f\"screen_{datetime.now().strftime('%Y%m%d_%H%M%S')}.png\"\n    p = subprocess.run([\"screencapture\", \"-x\", str(f)], capture_output=True, text=True, timeout=30)\n    ok = p.returncode == 0 and f.exists() and f.stat().st_size > 0\n    return {\"ok\": ok, \"file\": str(f), \"size\": f.stat().st_size if f.exists() else 0, \"stderr\": p.stderr[-800:]}\n\ndef bad_text(text):\n    s = \" \".join(str(text or \"\").lower().split())\n    return any(x in s for x in BAD_FRAGMENTS)\n\ndef parse_json(raw):\n    raw = str(raw or \"\").strip()\n    a, b = raw.find(\"{\"), raw.rfind(\"}\")\n    if a >= 0 and b > a:\n        return json.loads(raw[a:b+1])\n    return {}\n\ndef sanitize_note(data, active_window):\n    summary = str(data.get(\"summary\", \"\")).strip()\n    question = str(data.get(\"question\", \"\")).strip()\n    tags = data.get(\"tags\", [\"vision\"])\n    if not isinstance(tags, list):\n        tags = [\"vision\"]\n\n    if bad_text(summary) or not summary:\n        app = active_window.get(\"app\") or \"Unknown app\"\n        title = active_window.get(\"title\") or \"untitled window\"\n        summary = f\"Altan is using {app}. Active window: {title}.\"\n        question = \"\"\n        tags = [\"vision\", \"active_window\", app.lower().replace(\" \", \"_\")]\n\n    if bad_text(question):\n        question = \"\"\n\n    try:\n        importance = int(data.get(\"importance\", 0) or 0)\n    except Exception:\n        importance = 0\n\n    importance = max(importance, 68)\n    return {\"importance\": importance, \"summary\": summary[:900], \"question\": question[:400], \"tags\": tags}\n\ndef vision_json(path, active_window):\n    s = settings()\n    prompt = (\n        \"You are Seed's private screen-noting module. \"\n        \"Look at the screenshot and describe what Altan is actually doing on the Mac. \"\n        \"Do not repeat these instructions. Do not mention JSON, prompt, screenshot, or privacy policy in the summary. \"\n        \"Return only a compact JSON object with keys: importance, summary, question, tags. \"\n        \"The summary must be about the visible screen content, active app, terminal output, code, browser, or task. \"\n        \"Active window metadata: \" + json.dumps(active_window, ensure_ascii=False)\n    )\n    img = base64.b64encode(Path(path).read_bytes()).decode()\n    payload = {\n        \"model\": s.get(\"vision_model\"),\n        \"prompt\": prompt,\n        \"images\": [img],\n        \"stream\": False,\n        \"keep_alive\": \"30m\",\n        \"options\": {\"temperature\": 0.1, \"num_predict\": 220}\n    }\n    req = urllib.request.Request(s.get(\"ollama_url\"), data=json.dumps(payload).encode(), headers={\"Content-Type\":\"application/json\"}, method=\"POST\")\n    raw = json.loads(urllib.request.urlopen(req, timeout=75).read().decode()).get(\"response\", \"\")\n    data = parse_json(raw)\n    if not data:\n        data = {\"importance\": 0, \"summary\": \"\", \"question\": \"\", \"tags\": [\"vision\"], \"raw_error\": raw[:200]}\n    return sanitize_note(data, active_window)\n\ndef process_screen():\n    global _last\n    s = settings()\n    avatar(\"seeing\", \"Seed is looking. Screenshot will be deleted.\")\n    w = window()\n    sh = shot()\n    if not sh.get(\"ok\"):\n        return status(ok=False, mode=\"error\", error=sh.get(\"stderr\"), screenshot_saved=False)\n    try:\n        avatar(\"thinking\", \"Seed is deciding if what it sees matters.\")\n        try:\n            d = vision_json(sh[\"file\"], w)\n        except Exception as e:\n            key = f\"{w.get('app')}::{w.get('title')}\"\n            if key != _last:\n                d = {\"importance\": 68, \"summary\": f\"Altan's active screen changed to {w.get('app')} \u2014 {w.get('title') or 'untitled window'}.\", \"question\": \"\", \"tags\": [\"vision\", \"window_change\"], \"vision_error\": str(e)}\n                _last = key\n            else:\n                d = {\"importance\": 0, \"summary\": \"\", \"question\": \"\", \"tags\": [\"vision\"], \"vision_error\": str(e)}\n\n        imp = int(d.get(\"importance\", 0) or 0)\n        stored = False\n        saved = None\n        if imp >= int(s.get(\"min_importance_to_note\", 64)) and d.get(\"summary\"):\n            from seed_organism_notes_v89 import add_note\n            saved = add_note(\"vision\", d.get(\"summary\", \"\"), imp, d.get(\"question\", \"\"), d.get(\"tags\", [\"vision\"]), {\"active_window\": w, \"raw_screenshot_saved\": False})\n            stored = bool(saved.get(\"ok\"))\n        return status(ok=True, mode=\"seeing\", stored=stored, importance=imp, active_window=w, screenshot_deleted=True, saved=saved)\n    finally:\n        try:\n            if s.get(\"delete_screenshot_after_note\", True):\n                Path(sh[\"file\"]).unlink(missing_ok=True)\n        except Exception:\n            pass\n\ndef loop():\n    STOP_FILE.unlink(missing_ok=True)\n    print(\"=== Seed v89.1 ambient vision: screenshots deleted, prompt leaks blocked ===\")\n    while not STOP_FILE.exists():\n        if settings().get(\"enabled\", True):\n            try:\n                print(process_screen())\n            except Exception as e:\n                print({\"ok\": False, \"error\": str(e)})\n        time.sleep(float(settings().get(\"interval_seconds\", 90)))\n\ndef alive(pid):\n    try:\n        os.kill(int(pid), 0)\n        return True\n    except Exception:\n        return False\n\ndef start_daemon():\n    if PID_FILE.exists():\n        try:\n            pid = int(PID_FILE.read_text().strip())\n            if alive(pid):\n                return {\"ok\": True, \"already_running\": True, \"pid\": pid}\n        except Exception:\n            pass\n    STOP_FILE.unlink(missing_ok=True)\n    log = LOG_FILE.open(\"a\")\n    p = subprocess.Popen([sys.executable, \"seed_ambient_vision_v89.py\", \"loop\"], stdout=log, stderr=log)\n    PID_FILE.write_text(str(p.pid))\n    return {\"ok\": True, \"pid\": p.pid, \"log\": str(LOG_FILE)}\n\ndef stop_daemon():\n    STOP_FILE.write_text(now())\n    pid = None\n    stopped = False\n    if PID_FILE.exists():\n        try:\n            pid = int(PID_FILE.read_text().strip())\n            if alive(pid):\n                os.kill(pid, signal.SIGTERM)\n                stopped = True\n            PID_FILE.unlink(missing_ok=True)\n        except Exception:\n            pass\n    return {\"ok\": True, \"pid\": pid, \"stopped\": stopped}\n\ndef vision_status():\n    pid = None\n    a = False\n    if PID_FILE.exists():\n        try:\n            pid = int(PID_FILE.read_text().strip())\n            a = alive(pid)\n        except Exception:\n            pass\n    rt = {}\n    if STATUS_FILE.exists():\n        try:\n            rt = json.loads(STATUS_FILE.read_text(errors=\"ignore\"))\n        except Exception:\n            pass\n    return {\"created_at\": now(), \"version\": \"v89.1.0\", \"ok\": True, \"pid\": pid, \"alive\": a, \"settings\": settings(), \"runtime_status\": rt}\n\nif __name__ == \"__main__\":\n    a = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if a == \"start\":\n        print(start_daemon())\n    elif a == \"stop\":\n        print(stop_daemon())\n    elif a == \"loop\":\n        loop()\n    elif a == \"once\":\n        print(process_screen())\n    else:\n        print(json.dumps(vision_status(), indent=4, ensure_ascii=False))\n",
    "seed_v891_gate.py": "\nimport json, subprocess, sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nMODULES = [\"seed_organism_notes_v89.py\", \"seed_ambient_vision_v89.py\", \"seed_v891_gate.py\"]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef comp(m):\n    p = subprocess.run([sys.executable, \"-m\", \"py_compile\", m], capture_output=True, text=True, timeout=30)\n    return {\"module\": m, \"ok\": p.returncode == 0, \"stderr\": p.stderr[-1000:]}\n\ndef run_v891_gate():\n    checks = [comp(m) for m in MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n    details = {}\n    try:\n        from seed_organism_notes_v89 import is_bad_summary, settings\n        reject_ok = is_bad_summary(\"Inspect this temporary screenshot, then return ONLY JSON with importance 0-100\") is True\n        privacy = settings()\n        privacy_ok = privacy.get(\"store_raw_audio\") is False and privacy.get(\"store_raw_screenshots\") is False and privacy.get(\"store_raw_transcripts\") is False\n        details[\"reject_prompt_leak_test\"] = reject_ok\n        details[\"privacy\"] = privacy\n    except Exception as e:\n        reject_ok = False\n        privacy_ok = False\n        details[\"error\"] = str(e)\n    r = {\"created_at\": now(), \"version\": \"v89.1.0\", \"ready\": modules_ok and reject_ok and privacy_ok, \"modules_ok\": modules_ok, \"prompt_leak_reject_ok\": reject_ok, \"privacy_ok\": privacy_ok, \"module_checks\": checks, \"details\": details}\n    Path(\"seed_v891_gate_report.json\").write_text(json.dumps(r, indent=4, ensure_ascii=False))\n    return r\n\ndef show_v891_gate():\n    r = run_v891_gate()\n    print(\"\\n=== SEED v89.1 ORGANISM NOTE QUALITY GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Prompt Leak Reject OK: {r['prompt_leak_reject_ok']}\")\n    print(f\"Privacy OK: {r['privacy_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v891_gate()\n"
}

for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

p = Path("seed_config.py")
text = p.read_text(errors="ignore") if p.exists() else 'SEED_VERSION = "v89.1.0"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v89.1.0"', text, flags=re.M)
if "SEED_V891_ORGANISM_NOTE_QUALITY" not in text:
    text += "\nSEED_V891_ORGANISM_NOTE_QUALITY = True\nSEED_V891_PROMPT_LEAK_REJECT = True\n"
p.write_text(text)
print("Updated seed_config.py")

p = Path("Seed_Core.md")
text = p.read_text(errors="ignore") if p.exists() else ""
if "Seed v89.1 — Organism Note Quality Hotfix" not in text:
    text += """
## Seed v89.1 — Organism Note Quality Hotfix

Fixes v89 ambient vision note quality:
- Blocks prompt-leak notes like "Return ONLY JSON" or "Inspect this temporary screenshot".
- Cleans existing bad notes.
- Sanitizes model output before saving organism notes.
- Keeps privacy defaults: no raw audio, screenshots, or transcripts stored.
"""
p.write_text(text)
print("Updated Seed_Core.md")

for m in list(FILES.keys()):
    proc = subprocess.run([sys.executable, "-m", "py_compile", m], capture_output=True, text=True, timeout=30)
    print("$ python -m py_compile", m)
    if proc.returncode == 0:
        print("OK")
    else:
        print(proc.stderr)
        sys.exit(proc.returncode)

proc = subprocess.run([sys.executable, "seed_organism_notes_v89.py", "clean"], capture_output=True, text=True, timeout=30)
print("$ python seed_organism_notes_v89.py clean")
print(proc.stdout.strip())
if proc.returncode != 0:
    print(proc.stderr)

print("\nSeed v89.1 Organism Note Quality hotfix installed.")
